// ConnectorGuard-HDC FPGA wrapper for the AMD Kria KV260 (xck26-sfvc784-2LV-c).
//
// Clock and reset come from the Zynq UltraScale+ PS (pl_clk0 = 100 MHz,
// pl_resetn0), because the KV260 carrier has no oscillator wired to the PL.
// The PS block design "cg_ps" is generated by build.tcl.
//
// Only six slow outputs leave the chip. Everything wide is driven inside:
//   * sensor stream : pattern generator, one sample every SAMPLE_DIV clocks
//                     (250 kS/s at 100 MHz), operating point well below the
//                     M8 limits, plus LFSR noise. Mode SWITCH adds a ~31 kHz
//                     square ripple, mode ARC adds broadband noise.
//   * register bus  : sequencer that runs the README commissioning order
//                     (train switching, train arc, TRIP_CLEAR, LOCK_CFG) and
//                     then reads STATUS/FEAT0/FEAT1/HDC/HEALTH in rotation.
//   * replay port   : unused (src_sel = 0), so the replay buffer is removed
//                     by synthesis.
// heartbeat is a ~0.75 Hz blink whose phase is XORed with a signature of
// bus_rdata/health/cp_duty, so the readback logic stays in the netlist.
module cg_fpga_top
  import cg_pkg::*;
#(
  parameter int SAMPLE_DIV = 400,     // 100 MHz / 250 kS/s
  parameter int PWM_PERIOD = 100000,  // 100 MHz / 1 kHz control pilot
  parameter int TRAIN_SMP  = 1024     // samples per training phase (16 windows)
) (
  output logic       contactor_close,
  output logic [1:0] state,
  output logic       hard_trip,
  output logic       cp_pwm,
  output logic       heartbeat
);
  // ---------------- PS clock and reset ----------------
  logic clk, ps_rst_n;
  cg_ps u_ps (
    .pl_clk0   (clk),
    .pl_resetn0(ps_rst_n)
  );

  // asynchronous assert, synchronous release
  (* ASYNC_REG = "TRUE" *) logic [1:0] rst_sync;
  logic rst_n;
  always_ff @(posedge clk or negedge ps_rst_n) begin
    if (!ps_rst_n) rst_sync <= 2'b00;
    else           rst_sync <= {rst_sync[0], 1'b1};
  end
  assign rst_n = rst_sync[1];

  // ---------------- pattern generator ----------------
  localparam logic [1:0] GEN_NORMAL = 2'd0;
  localparam logic [1:0] GEN_SWITCH = 2'd1;
  localparam logic [1:0] GEN_ARC    = 2'd2;

  logic [$clog2(SAMPLE_DIV)-1:0] div_cnt;
  logic        smp_tick;
  logic [15:0] lfsr;
  logic [7:0]  smp_idx;
  logic [1:0]  gen_mode;
  logic        live_valid;
  sample_t     live_data;

  assign smp_tick = (div_cnt == '0);

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      div_cnt <= '0;
      lfsr    <= 16'hACE1;
      smp_idx <= '0;
    end else begin
      div_cnt <= (div_cnt == ($clog2(SAMPLE_DIV))'(SAMPLE_DIV - 1)) ? '0 : div_cnt + 1'b1;
      if (smp_tick) begin
        lfsr    <= {lfsr[14:0], 1'b0} ^ (lfsr[15] ? 16'h002D : 16'h0000);
        smp_idx <= smp_idx + 1'b1;
      end
    end
  end

  // Operating point: 32 A, 3.2 mV contact drop (0.1 mOhm), 35 degC connector,
  // 25 degC ambient, 1 mA residual current.
  logic signed [15:0] noise_s, ripple, i_now, v_now;
  assign noise_s = signed'({10'd0, lfsr[5:0]}) - 16'sd32;             // -32..31
  always_comb begin
    unique case (gen_mode)
      GEN_SWITCH: ripple = smp_idx[2] ? 16'sd600 : -16'sd600;
      GEN_ARC:    ripple = signed'({5'd0, lfsr[15:5]}) - 16'sd1024;     // -1024..1023
      default:    ripple = 16'sd0;
    endcase
    i_now = 16'sd3200 + noise_s + ripple;
    v_now = 16'sd320 + (noise_s >>> 2) + (ripple >>> 4);
  end

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      live_valid <= 1'b0;
      live_data  <= '0;
    end else begin
      live_valid <= smp_tick;
      if (smp_tick) begin
        live_data.i    <= i_now;
        live_data.v    <= v_now;
        live_data.t    <= 16'sd560 + signed'({14'd0, lfsr[9:8]});
        live_data.tamb <= 16'sd400;
        live_data.ires <= 16'd10 + {14'd0, lfsr[11:10]};
      end
    end
  end

  // ---------------- commissioning sequencer + readback ----------------
  typedef struct packed {
    logic [31:0] wdata;    // written to CMD (0x02)
    logic [1:0]  mode;     // generator mode while waiting
    logic [15:0] wait_smp; // samples to wait after the write
  } step_t;

  localparam int NSTEP = 7;
  function automatic step_t step_rom(input logic [2:0] k);
    unique case (k)
      3'd0:    return '{32'h0000_0000, GEN_NORMAL, 16'd64};               // M8 arms, M5b/M6 clear passes
      3'd1:    return '{32'h0000_0110, GEN_SWITCH, 16'(TRAIN_SMP)};       // TRAIN_START label 1
      3'd2:    return '{32'h0000_0020, GEN_NORMAL, 16'd64};               // TRAIN_STOP
      3'd3:    return '{32'h0000_0210, GEN_ARC,    16'(TRAIN_SMP)};       // TRAIN_START label 2
      3'd4:    return '{32'h0000_0020, GEN_NORMAL, 16'd256};              // TRAIN_STOP
      3'd5:    return '{32'h0000_0002, GEN_NORMAL, 16'd4};                // TRIP_CLEAR
      default: return '{32'h0000_0001, GEN_NORMAL, 16'd0};                // LOCK_CFG
    endcase
  endfunction

  logic [2:0]  step;
  logic        seq_done, step_wr;
  logic [15:0] wait_cnt;
  step_t       cur;
  assign cur = step_rom(step);

  logic        bus_wr, bus_rd;
  logic [7:0]  bus_addr;
  logic [31:0] bus_wdata, bus_rdata;
  logic [2:0]  rd_sel;

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      step     <= '0;
      seq_done <= 1'b0;
      step_wr  <= 1'b1;
      wait_cnt <= '0;
      gen_mode <= GEN_NORMAL;
      rd_sel   <= '0;
    end else if (!seq_done) begin
      if (step_wr) begin
        step_wr  <= 1'b0;
        wait_cnt <= cur.wait_smp;
        gen_mode <= cur.mode;
      end else if (wait_cnt != '0) begin
        if (smp_tick) wait_cnt <= wait_cnt - 1'b1;
      end else if (step == 3'(NSTEP - 1)) begin
        seq_done <= 1'b1;
      end else begin
        step    <= step + 1'b1;
        step_wr <= 1'b1;
      end
    end else begin
      rd_sel <= (rd_sel == 3'd4) ? 3'd0 : rd_sel + 1'b1;
    end
  end

  always_comb begin
    bus_wr    = !seq_done && step_wr && (cur.wdata != 32'd0);
    bus_wdata = cur.wdata;
    bus_rd    = seq_done;
    unique case (rd_sel)
      3'd0:    bus_addr = seq_done ? 8'h01 : 8'h02;
      3'd1:    bus_addr = 8'h03;
      3'd2:    bus_addr = 8'h04;
      3'd3:    bus_addr = 8'h05;
      default: bus_addr = 8'h06;
    endcase
  end

  // ---------------- IP core ----------------
  logic       live_ready, rp_busy;
  logic [7:0] cp_duty, health;
  cg_top #(.PWM_PERIOD(PWM_PERIOD)) u_core (
    .clk, .rst_n,
    .live_valid, .live_data, .live_ready,
    .src_sel(1'b0), .rp_wr_en(1'b0), .rp_wr_addr('0), .rp_wr_data('0),
    .rp_start(1'b0), .rp_len('0), .rp_period('0), .rp_busy,
    .bus_wr, .bus_rd, .bus_addr, .bus_wdata, .bus_rdata,
    .contactor_close, .cp_pwm, .cp_duty, .state, .hard_trip, .health
  );

  // ---------------- heartbeat ----------------
  logic [31:0] sig;
  logic [26:0] blink;
  logic        sig_bit;
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      sig     <= '0;
      blink   <= '0;
      sig_bit <= 1'b0;
    end else begin
      sig   <= {sig[30:0], sig[31]} ^ bus_rdata ^ {16'd0, cp_duty, health};
      blink <= blink + 1'b1;
      if (blink == '1) sig_bit <= ^sig;
    end
  end
  assign heartbeat = blink[26] ^ sig_bit;

endmodule
